import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {withRetries} from '@github-ui/workspace-editor/utilities/with-retries'
import {createContext, useCallback, useContext, useEffect, useMemo, useRef, useState} from 'react'

import {useStableCallback} from '../hooks/use-stable-callback'
import {useAnalytics} from '../telemetry/use-analytics'
import type {CommitData, GitFileStatuses} from '../types/file-syncer-v2-types'
// import type {FileDescription} from '../types/spark-history-types'
import type {Iteration, IterationMetadata, WorkbenchRoutePayload} from '../types/workbench-types'
import {USER_EDIT_COMMIT_MESSAGE} from '../utilities/commit-messages'
import {useFileSyncerContext} from './FileSyncerContext'
import {useWorkbenchContext} from './WorkbenchContext'

export type IterationHistoryContext = {
  setCurrentRefinement: (refinementId: number | undefined, saveToLocalStorage?: boolean) => void
  previousRefinements: Iteration[]
  setPreviousRefinements: (value: Iteration[] | ((prev: Iteration[]) => Iteration[])) => void
  currentRefinementId: number | undefined
  isNavigatingHistory: boolean
  setIsNavigatingHistory: (value: boolean) => void
  updateUserEditStatus: (message: string) => Promise<void>
  updateIterationsFromServer: () => Promise<void>
  currentRefinementSha: string | undefined
  previousRefinementSha: string | null
  updateLatestCommitShas: () => Promise<void>
  isInitialIteration: boolean
  refreshGitHistory: () => Promise<void>
  notifyRehydrateCompleted: () => void
  gitHistoryRestored: boolean
}

const POLL_FOR_USER_EDITS_INTERVAL = 15 * 1000 // Poll every 15 seconds
type PollingStateData = {
  previousRefinements: Iteration[]
  currentRefinementId: number | undefined
  currentRefinementSha?: string
  fileSyncerStarted: boolean
  isFetching: boolean
}

export function IterationHistoryProvider({children}: {children: React.ReactNode}) {
  const {workbench} = useRoutePayload<WorkbenchRoutePayload>()
  const iterationsInDbRef = useRef<Iteration[]>(workbench.previousRefinements || [])
  const createManualIterationOnFileEdit = useFeatureFlag('spark_create_manual_iteration_on_file_edit')
  const sendEvent = useAnalytics()

  const [previousRefinements, setPreviousRefinements] = useState<Iteration[]>(workbench.previousRefinements || [])
  const initialRefinmentId = workbench.currentRefinementId ? workbench.currentRefinementId : undefined
  const [currentRefinementId, setCurrentRefinementId] = useState<number | undefined>(initialRefinmentId)
  const [currentRefinementSha, setCurrentRefinementSha] = useState<string | undefined>()
  const [isNavigatingHistory, setIsNavigatingHistory] = useState(false)
  const [gitHistoryRestored, setGitHistoryRestored] = useState(false)
  const shaFilesMapRef = useRef<Map<string, GitFileStatuses>>(new Map())
  const {
    getFileSyncerV2,
    fileSyncerStarted,
    syncerMode,
    forceContentRefresh,
    forceFileTreeRefresh,
    lastEditStateStamp,
  } = useFileSyncerContext()
  const pollForUserEditsInterval = useRef<ReturnType<typeof setInterval> | undefined>(undefined)
  const {isFetching} = useWorkbenchContext()
  const refreshHistoryRef = useRef<Promise<void> | null>(null)
  // Using a ref here since we're scheduling an interval that needs to access the latest state
  // without causing re-renders.
  const pollingStateRef = useRef<PollingStateData>({
    previousRefinements,
    currentRefinementId,
    currentRefinementSha,
    fileSyncerStarted,
    isFetching,
  })

  const setCurrentRefinement = useStableCallback((refinementId: number | undefined) => {
    setCurrentRefinementId(refinementId)
    if (refinementId === undefined) {
      setCurrentRefinementSha(undefined)
    }

    const refinement = previousRefinements.find(ref => ref.id === refinementId)
    if (refinement) {
      setCurrentRefinementSha(refinement.sha)
    }
  })

  const iterationMetadataToIteration = useCallback(
    (iterationMetadata: IterationMetadata): Iteration => {
      const {id, parentId} = workbench.previousRefinements.find(ref => ref.sha === iterationMetadata.sha) || {}
      return {
        ...iterationMetadata,
        id,
        parentId,
      }
    },
    [workbench.previousRefinements],
  )

  const commitDataToIteration = useCallback((commitData: CommitData): Iteration => {
    const iterationInDb = iterationsInDbRef.current.find(ref => ref.sha === commitData.sha)

    const iteration_type =
      iterationInDb?.iteration_type ?? commitData.message?.startsWith('Generated by Spark:') ? 'ai' : 'user'
    const suggestions = iterationInDb?.suggestions ?? []
    const files = iterationInDb?.files ?? {}
    const id = iterationInDb?.id
    const parentId = iterationInDb?.parentId ?? null
    let prompt = iterationInDb?.prompt
    if (iteration_type === 'ai' && !prompt) {
      prompt = commitData.message?.replace('Generated by Spark:', '').trim()
    }

    return {
      ...commitData,
      id,
      parentId,
      files,
      prompt,
      iteration_type,
      suggestions,
    }
  }, [])

  const timestampOfLastEdit = useMemo(() => {
    if (createManualIterationOnFileEdit) {
      return lastEditStateStamp
    }

    return 0
  }, [createManualIterationOnFileEdit, lastEditStateStamp])

  const updateLatestCommitShas = useCallback(async () => {
    const fileSyncer = getFileSyncerV2()
    if (!fileSyncer || !fileSyncerStarted) {
      return
    }
    const metadata = await fileSyncer.getLastCommit()
    const iteration = iterationMetadataToIteration(metadata)
    setCurrentRefinement(iteration.id)
    setCurrentRefinementSha(iteration.sha)
  }, [fileSyncerStarted, getFileSyncerV2, iterationMetadataToIteration, setCurrentRefinement])

  const updateRefinementsFromCommits = useCallback(
    async (iterations: Iteration[], headSha: string) => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer || !fileSyncerStarted) {
        return
      }

      if (!copilotFeatureFlags.sparkReadIterationHistoryFromGitV2) {
        return
      }

      let files = await fileSyncer.getGitStatus()
      if (Object.keys(files).length > 0) {
        const tempIteration = {
          iteration_type: 'user',
          files,
          parentSha: headSha,
          sha: undefined,
        } satisfies Iteration
        setPreviousRefinements([...iterations, tempIteration])
        setCurrentRefinementSha(tempIteration.sha)
      } else {
        files = await fileSyncer.getChangedFilesFiltered(headSha)
        if (Object.keys(files).length > 0) {
          shaFilesMapRef.current.set(headSha, files)
          const headIterationIndex = iterations.findLastIndex(iteration => iteration.sha === headSha)
          if (headIterationIndex !== -1) {
            const headIteration = iterations[headIterationIndex]
            if (headIteration) {
              headIteration.files = files
            }
          }
          setPreviousRefinements([...iterations])
        }
        setCurrentRefinementSha(headSha)
      }
    },
    [fileSyncerStarted, getFileSyncerV2],
  )

  const fetchIterationHistoryFromGitV2 = useCallback(async () => {
    const fileSyncer = getFileSyncerV2()
    const commitHistoryAll = await withRetries(() => fileSyncer?.getCommitHistory(), {
      retries: 3,
      retryDelayMs: 500,
      exponentialBackoffFactor: 1.5,
    })
    const headSha = commitHistoryAll?.find(commit => commit.isHead)?.sha

    // Filter out commits that don't have a parentSha, essentially ignoring the initial commit since it won't have a parent.
    const commitHistory = commitHistoryAll?.filter(commit => commit.parentSha)

    if (!headSha) {
      throw new Error('Unable to determine head SHA from commit history')
    }

    const iterations: Iteration[] = commitHistory?.map(commitDataToIteration).reverse() || []
    const currentRefinement = iterations.find(iteration => iteration.sha === headSha)
    return {iterations, currentRefinement}
  }, [commitDataToIteration, getFileSyncerV2])

  const fetchIterationHistoryFromGit = useCallback(async () => {
    const fileSyncer = getFileSyncerV2()
    const iterationHistory = await withRetries(() => fileSyncer?.getIterationHistory(), {
      retries: 3,
      retryDelayMs: 500,
      exponentialBackoffFactor: 1.5,
    })
    const iterations: Iteration[] = iterationHistory?.map(iterationMetadataToIteration) || []
    const lastCommitData = await fileSyncer?.getLastCommit()
    const currentRefinement = lastCommitData ? iterationMetadataToIteration(lastCommitData) : undefined
    return {iterations, currentRefinement}
  }, [getFileSyncerV2, iterationMetadataToIteration])

  const refreshGitHistory = useCallback(async () => {
    // If there's already a request in progress, return the existing one
    if (refreshHistoryRef.current) {
      return refreshHistoryRef.current
    }

    // Create and execute a new async function for this request
    const refreshHistory = (async () => {
      try {
        let result: {iterations: Iteration[]; currentRefinement?: Iteration}
        if (copilotFeatureFlags.sparkReadIterationHistoryFromGitV2) {
          result = await fetchIterationHistoryFromGitV2()
          const headSha = result.currentRefinement?.sha || ''
          const files = shaFilesMapRef.current.get(headSha)
          if (files) {
            const iteration = result.iterations.find(x => x.sha === headSha)
            if (iteration) {
              iteration.files = files
            }
          }

          setPreviousRefinements(result.iterations)
          await updateRefinementsFromCommits(result.iterations, headSha)
        } else {
          result = await fetchIterationHistoryFromGit()
          setPreviousRefinements(result.iterations)
          await updateLatestCommitShas()
        }

        sendEvent('iteration_history.refresh_git_history_success', {
          iteration_count: result.iterations.length ?? 0,
        })
      } catch (error) {
        sendEvent('iteration_history.refresh_git_history_error', {
          error: error instanceof Error ? error.message : String(error),
        })
      } finally {
        // Clear the promise ref when done
        refreshHistoryRef.current = null
      }
    })()

    refreshHistoryRef.current = refreshHistory

    return refreshHistory
    // don't include sendEvent because its constantly changing
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fetchIterationHistoryFromGit, updateLatestCommitShas])

  const notifyRehydrateCompleted = useCallback(() => {
    setGitHistoryRestored(true)
  }, [])

  useEffect(() => {
    if (
      !copilotFeatureFlags.sparkReadIterationHistoryFromGit &&
      !copilotFeatureFlags.sparkReadIterationHistoryFromGitV2
    ) {
      return
    }
    if (!fileSyncerStarted || syncerMode !== 'codespace') return
    if (!gitHistoryRestored) return
    if (isFetching) return

    refreshGitHistory()
    // timestampOfLastEdit is included to ensure we refresh history after user edits
  }, [fileSyncerStarted, isFetching, refreshGitHistory, syncerMode, gitHistoryRestored, timestampOfLastEdit])

  pollingStateRef.current = {
    previousRefinements,
    currentRefinementId,
    fileSyncerStarted,
    isFetching,
  }

  const updateUserEditStatus = useCallback(
    async (message: string) => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer || !fileSyncerStarted) {
        return
      }
      const statusResults = await fileSyncer.getGitStatus()
      const currentRefinement = previousRefinements.find(ref => ref.id === currentRefinementId)

      if (!currentRefinement || currentRefinement.iteration_type !== 'user' || currentRefinement.sha) {
        const updatedRefinement: Iteration = {
          prompt: message,
          iteration_type: 'user',
          parentId: currentRefinementId || undefined,
          files: statusResults,
        }
        setPreviousRefinements(prev => [...prev, updatedRefinement])
        setCurrentRefinement(updatedRefinement.id)
      } else {
        // If there are no file changes, but we had an in-progress user edit, remove it.
        if (Object.keys(statusResults).length === 0) {
          setPreviousRefinements(prev => prev.filter(ref => ref.id !== currentRefinementId))
          setCurrentRefinement(currentRefinement.parentId || undefined)
          return
        }

        // If the user is editing an existing user iteration, we need to update the files
        const updatedRefinement = {
          ...currentRefinement,
          files: statusResults,
        }
        setPreviousRefinements(prev => {
          const newPreviousRefinements = [...prev]
          const currentRefinementIndex = prev.findIndex(ref => ref.id === currentRefinementId)
          newPreviousRefinements[currentRefinementIndex] = updatedRefinement
          return newPreviousRefinements
        })
      }
    },
    [currentRefinementId, fileSyncerStarted, getFileSyncerV2, previousRefinements, setCurrentRefinement],
  )

  const updateIterationsFromServer = useCallback(async () => {
    if (copilotFeatureFlags.sparkReadIterationHistoryFromGit) {
      const {iterations, currentRefinement} = await fetchIterationHistoryFromGit()
      setPreviousRefinements(iterations)
      setCurrentRefinementSha(currentRefinement?.sha)
    }
    if (copilotFeatureFlags.sparkReadIterationHistoryFromGitV2) {
      // Fetch the iterations from DB first so that metadata can be merged with commits from git
      const {iterations: iterationsFetchedFromDb} = await fetchIterationsFromDb()
      iterationsInDbRef.current = iterationsFetchedFromDb
      const {iterations, currentRefinement} = await fetchIterationHistoryFromGitV2()
      setPreviousRefinements(iterations)
      setCurrentRefinementSha(currentRefinement?.sha)
    } else {
      const {iterations, current_iteration_id: newCurrentRefinementId} = await fetchIterationsFromDb()
      setPreviousRefinements(iterations)
      setCurrentRefinement(newCurrentRefinementId)
    }
    forceContentRefresh()
    forceFileTreeRefresh()

    async function fetchIterationsFromDb() {
      const response = await verifiedFetchJSON(`/copilot/spark/workbench/${workbench.id}/iterations`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      })
      const {iterations, current_iteration_id} = await response.json()
      return {iterations, current_iteration_id}
    }
  }, [
    fetchIterationHistoryFromGit,
    fetchIterationHistoryFromGitV2,
    forceContentRefresh,
    forceFileTreeRefresh,
    setCurrentRefinement,
    workbench.id,
  ])

  useEffect(() => {
    async function initializeUserStatus() {
      const {
        previousRefinements: prevRefinements,
        currentRefinementId: refinementId,
        fileSyncerStarted: isFileSyncerStarted,
        isFetching: isGenerating,
      } = pollingStateRef.current

      if (isGenerating) {
        // If a generation is in progress, we don't want to poll for user edits
        return
      }

      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer || !isFileSyncerStarted) {
        return
      }
      const statusResults = await fileSyncer.getGitStatus()
      const currentRefinement = prevRefinements.find(ref => ref.id === refinementId)
      const hasInProgreessUserEdit =
        currentRefinement && currentRefinement.iteration_type === 'user' && !currentRefinement.sha

      if (Object.keys(statusResults).length <= 0) {
        // Check if we had an in progress user edit, if so, we need to clear it
        if (hasInProgreessUserEdit) {
          setPreviousRefinements(prev => prev.filter(ref => ref.id !== refinementId))
          setCurrentRefinement(currentRefinement.parentId || undefined)
        }
        return
      }

      if (!hasInProgreessUserEdit) {
        const updatedRefinement: Iteration = {
          prompt: USER_EDIT_COMMIT_MESSAGE,
          iteration_type: 'user',
          parentId: refinementId || undefined,
          files: statusResults,
        }
        setPreviousRefinements(prev => [...prev, updatedRefinement])
        setCurrentRefinement(updatedRefinement.id)
        return
      }

      // If the user is editing an existing user iteration, we need to update the files
      const updatedRefinement = {
        ...currentRefinement,
        files: statusResults,
      }
      setPreviousRefinements(prev => {
        const newPreviousRefinements = [...prev]
        const currentRefinementIndex = prev.findIndex(ref => ref.id === refinementId)
        newPreviousRefinements[currentRefinementIndex] = updatedRefinement
        return newPreviousRefinements
      })
    }
    if (
      copilotFeatureFlags.sparkReadIterationHistoryFromGit ||
      copilotFeatureFlags.sparkReadIterationHistoryFromGitV2
    ) {
      // If we're reading iteration history from git, we don't need to poll for user edits
      return
    }
    initializeUserStatus()
    clearInterval(pollForUserEditsInterval.current)
    pollForUserEditsInterval.current = setInterval(initializeUserStatus, POLL_FOR_USER_EDITS_INTERVAL)
    return () => {
      clearInterval(pollForUserEditsInterval.current)
    }
  }, [fileSyncerStarted, getFileSyncerV2, timestampOfLastEdit, setCurrentRefinement])

  const {previousRefinementSha} = useMemo(() => {
    const currIndex = previousRefinements.findIndex(ref => ref.id === currentRefinementId)
    const prevRefinement = previousRefinements[currIndex - 1]
    return {
      currentRefinementIndex: currIndex,
      previousRefinementSha: prevRefinement?.sha || null,
    }
  }, [currentRefinementId, previousRefinements])

  const isInitialIteration = useMemo(() => {
    return (
      !previousRefinements ||
      !previousRefinements.length ||
      !previousRefinements.some(x => x.iteration_type === 'ai' && x.sha)
    )
  }, [previousRefinements])

  const value = useMemo(
    () => ({
      setPreviousRefinements,
      setCurrentRefinement,
      previousRefinements,
      currentRefinementId,
      isNavigatingHistory,
      setIsNavigatingHistory,
      updateUserEditStatus,
      updateIterationsFromServer,
      currentRefinementSha,
      previousRefinementSha,
      updateLatestCommitShas,
      isInitialIteration,
      refreshGitHistory,
      notifyRehydrateCompleted,
      gitHistoryRestored,
    }),
    [
      currentRefinementId,
      currentRefinementSha,
      isNavigatingHistory,
      isInitialIteration,
      previousRefinementSha,
      previousRefinements,
      setCurrentRefinement,
      updateIterationsFromServer,
      updateLatestCommitShas,
      updateUserEditStatus,
      refreshGitHistory,
      notifyRehydrateCompleted,
      gitHistoryRestored,
    ],
  )
  return <IterationHistoryContext.Provider value={value}>{children}</IterationHistoryContext.Provider>
}

export const IterationHistoryContext = createContext<IterationHistoryContext | undefined>(undefined)

export function useIterationHistory() {
  const context = useContext(IterationHistoryContext)
  if (!context) {
    throw new Error('useIterationHistory must be used within an IterationHistoryProvider')
  }
  return context
}

try{ IterationHistoryProvider.displayName ||= 'IterationHistoryProvider' } catch {}
try{ IterationHistoryContext.displayName ||= 'IterationHistoryContext' } catch {}